code.java:
class Solution {
    public boolean divideArray(int[] nums){
        Set<Integer> odd=new HashSet<>();
        for(int value:nums)if(!odd.add(value))odd.remove(value);
        return odd.isEmpty();
    }
}

code.kotlin:
class Solution {
    fun divideArray(nums:IntArray):Boolean{
        val odd=HashSet<Int>();
        for(value in nums)if(!odd.add(value))odd.remove(value);
        return odd.isEmpty()
    }
}

code.cpp:
class Solution {
    public:bool divideArray(vector<int>& nums){
        unordered_set<int> odd;
        for(int value:nums)if(odd.count(value))odd.erase(value);
        else odd.insert(value);
        return odd.empty();
    }
};
